import {createClient} from 'npm:@supabase/supabase-js@2';
import {authorizeSchoolCoach} from './authorize.ts';
import {inspectVideo} from './media.ts';
const allowed=new Set(['https://duairlineseliteacademy.com','https://www.duairlineseliteacademy.com']);const MAX=35*1024*1024;const BUCKET='technique-review';const uuid=(x:unknown)=>typeof x==='string'&&/^[0-9a-f-]{36}$/i.test(x);
Deno.serve(async req=>{const origin=req.headers.get('origin')||'';if(!allowed.has(origin))return new Response('Forbidden',{status:403});const headers={'access-control-allow-origin':origin,'access-control-allow-headers':'content-type,apikey,x-du-session','access-control-allow-methods':'POST,OPTIONS','content-type':'application/json','cache-control':'no-store'};const reply=(code:number,data:unknown)=>new Response(JSON.stringify(data),{status:code,headers});if(req.method==='OPTIONS')return reply(200,{});if(req.method!=='POST')return reply(405,{error:'Method not allowed'});try{const db=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});const body=await req.json();const {cohort,session}=await authorizeSchoolCoach(db,req.headers.get('x-du-session')||'');const clips=db.from('school_technique_clips');if(body.action==='context'){const {data:organization}=await db.from('cohorts').select('name,organization_id').eq('id',cohort.id).single();return reply(200,{cohortName:organization?.name||'School',cohortId:cohort.id});}
if(body.action==='list'){const {data,error}=await clips.select('id,athlete_name,coach_note,review_state,feedback,upload_state,created_at').eq('cohort_id',cohort.id).in('upload_state',['ready','deleted']).order('created_at',{ascending:false}).limit(50);if(error)throw error;return reply(200,{clips:data||[]});}
if(body.action==='reserve'){const name=String(body.athleteName||'').trim(),note=String(body.note||'').trim();if(name.length<1||name.length>100||note.length>1000)return reply(400,{error:'Enter the athlete name and a short note.'});const {count,error:ce}=await clips.select('id',{count:'exact',head:true}).eq('cohort_id',cohort.id).gte('created_at',new Date(Date.now()-7*86400000).toISOString()).in('upload_state',['ready','uploading','reserved']);if(ce)throw ce;if((count||0)>=30)return reply(429,{error:'School weekly video limit reached (30).'});const {data:clip,error}=await clips.insert({cohort_id:cohort.id,session_id:session.id,athlete_name:name,coach_note:note}).select('id').single();if(error||!clip)throw error||Error('Unable to create upload');const ext=body.mimeType==='video/quicktime'?'mov':'mp4';const path='school/'+cohort.id+'/'+clip.id+'.'+ext;const {data:upload,error:ue}=await db.storage.from(BUCKET).createSignedUploadUrl(path);if(ue||!upload){await clips.update({upload_state:'failed'}).eq('id',clip.id);return reply(503,{error:'Video storage unavailable'});}await clips.update({object_key:path,upload_state:'uploading'}).eq('id',clip.id);return reply(200,{id:clip.id,path,token:upload.token,maxBytes:MAX,maxSeconds:20});}
if(body.action==='finalize'){if(!uuid(body.id))return reply(400,{error:'Invalid video'});const {data:clip}=await clips.select('id,object_key,upload_state').eq('id',body.id).eq('cohort_id',cohort.id).maybeSingle();if(!clip||clip.upload_state!=='uploading')return reply(409,{error:'Upload not ready'});const {data:file,error:fe}=await db.storage.from(BUCKET).download(clip.object_key);if(fe||!file)return reply(409,{error:'File missing'});let durationMs=0;try{if(file.size<1||file.size>MAX)throw Error('Video must be under 35 MB');durationMs=inspectVideo(new Uint8Array(await file.arrayBuffer())).durationMs;}catch(e){await db.storage.from(BUCKET).remove([clip.object_key]);await clips.update({upload_state:'failed'}).eq('id',clip.id);return reply(400,{error:e instanceof Error?e.message:'Invalid video'});}const {error:ue}=await clips.update({upload_state:'ready',duration_ms:durationMs,byte_size:file.size}).eq('id',clip.id);if(ue)throw ue;return reply(200,{ok:true});}
if(body.action==='playback'){if(!uuid(body.id))return reply(400,{error:'Invalid video'});const {data:clip}=await clips.select('object_key').eq('id',body.id).eq('cohort_id',cohort.id).eq('upload_state','ready').maybeSingle();if(!clip?.object_key)return reply(404,{error:'Video deleted or unavailable'});const {data:signed,error}=await db.storage.from(BUCKET).createSignedUrl(clip.object_key,60);if(error||!signed)return reply(503,{error:'Video unavailable'});return reply(200,{url:signed.signedUrl});}return reply(400,{error:'Unknown action'});
}catch(e){console.error('School video error',e);return reply(403,{error:'School access expired or video service unavailable'});}});

// Staff access is verified using the existing school-code session.
// This helper is for a service-role Edge Function only, never browser code.
export async function authorizeSchoolCoach(db: any, token: string, athleteId?: string) {
  if (!token || token.length < 16 || token.length > 256) throw Error('Session expired');
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(token));
  const hash = Array.from(new Uint8Array(digest), x => x.toString(16).padStart(2, '0')).join('');
  const { data: session } = await db.from('hub_sessions').select('id,role,staff_id,cohort_id,access_code_id,expires_at,revoked_at').eq('token_hash', hash).maybeSingle();
  if (!session || session.role !== 'staff' || session.revoked_at || Date.parse(session.expires_at) <= Date.now()) throw Error('Session expired');
  const { data: code } = await db.from('access_codes').select('status,code_type,cohort_id,staff_id,expires_at').eq('id', session.access_code_id).maybeSingle();
  if (!code || code.status !== 'active' || code.code_type !== 'staff' || code.cohort_id !== session.cohort_id || (code.expires_at && Date.parse(code.expires_at) <= Date.now())) throw Error('Access revoked');
  const { data: cohort } = await db.from('cohorts').select('id,programme_id,status').eq('id', session.cohort_id).maybeSingle();
  if (!cohort || cohort.status !== 'live' || !cohort.programme_id) throw Error('Cohort unavailable');
  // Existing school staff codes are cohort-scoped and may intentionally be shared.
  // If a code identifies an individual staff member, enforce their assignment too.
  if (code.staff_id) {
    const { data: assignment } = await db.from('staff_cohorts').select('staff_id').eq('staff_id', code.staff_id).eq('cohort_id', cohort.id).maybeSingle();
    if (!assignment) throw Error('Coach not assigned');
  }
  let athlete = null;
  if (athleteId) {
    const { data } = await db.from('athletes').select('id,cohort_id,access_status').eq('id', athleteId).eq('cohort_id', cohort.id).eq('access_status', 'active').maybeSingle();
    if (!data) throw Error('Athlete not in assigned cohort');
    athlete = data;
  }
  return { session, cohort, athlete };
}

// ISO BMFF/QuickTime duration validator. Rejects malformed/fragmented files.
export function inspectVideo(bytes: Uint8Array): {durationMs:number; format:string} {
  if (bytes.length < 32) throw Error('Invalid video');
  const d = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const u32 = (p:number) => d.getUint32(p);
  const tag = (p:number) => String.fromCharCode(...bytes.subarray(p,p+4));
  let brand='', movie=false, fragmented=false;
  const durations:number[]=[];
  function boxes(start:number,end:number,depth:number):void {
    if(depth>8)throw Error('Invalid container');
    let p=start;
    while(p+8<=end) {
      let size=u32(p), head=8; const kind=tag(p+4);
      if(size===1) {
        if(p+16>end)throw Error('Invalid box');
        const high=u32(p+8);if(high!==0)throw Error('Oversized box');
        size=u32(p+12);head=16;
      } else if(size===0)size=end-p;
      if(size<head || p+size>end)throw Error('Malformed box');
      if(kind==='ftyp'){if(size<16)throw Error('Invalid ftyp');brand=tag(p+head);}
      if(kind==='moof')fragmented=true;
      if(kind==='moov')movie=true;
      if(kind==='mvhd'||kind==='mdhd') {
        const q=p+head,version=bytes[q];
        if(version!==0&&version!==1)throw Error('Unsupported media version');
        const offset=kind==='mvhd'?(version===1?20:12):(version===1?20:12);
        const at=q+offset,need=version===1?12:8;
        if(at+need>p+size)throw Error('Truncated duration');
        const scale=u32(at);
        const ticks=version===1?u32(at+4)*4294967296+u32(at+8):u32(at+4);
        if(scale===0||!Number.isSafeInteger(ticks))throw Error('Invalid duration');
        durations.push(ticks*1000/scale);
      }
      if(['moov','trak','mdia'].includes(kind))boxes(p+head,p+size,depth+1);
      p+=size;
    }
    if(p!==end)throw Error('Invalid trailing bytes');
  }
  boxes(0,bytes.length,0);
  if(!brand||!movie||fragmented||durations.length===0)throw Error('Unsupported video container');
  const durationMs=Math.ceil(Math.max(...durations));
  if(durationMs<1||durationMs>20000)throw Error('Video must be 20 seconds or shorter');
  return {durationMs,format:brand};
}
